import std.io

pub type AppError = Failed(String)

record Counter { n: Int64 }

impl Counter {
    fn bump(mut self) -> Int64 {
        self.n = self.n + 1
        self.n
    }
}

interface Greeter {
    fn greet(self) -> String
    fn greetLoud(self) -> String {
        self.greet() + "!"
    }
}

record User { name: String }

impl Greeter for User {
    fn greet(self) -> String {
        "hi"
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let c = Counter { n: 0 }
    io.println("${c.bump()} ${c.bump()}")
    let u = User { name: "a" }
    io.println(u.greetLoud())
    return Ok(())
}
